{"explanation":"A Riemann sum partitions the interval into thin rectangles and adds their areas. Here, each rectangle uses the function value at its right edge; increasing the number of rectangles makes the approximation approach the exact area, \(\int_0^2 x^2\,dx=8/3\).","manimCode":"const axes = new Axes({
  xRange: [-0.25, 2.35, 0.5],
  yRange: [-0.4, 4.7, 1],
  xLength: 8.5,
  yLength: 5.6,
  tips: true
});
axes.moveTo([0, -0.35, 0]);

const curve = axes.plot(x => x * x, { color: YELLOW, xRange: [0, 2], numSamples: 200 });
const title = new MathTex({ latex: '\\text{Riemann sums for }\\int_0^2 x^2\\,dx' });
await title.waitForRender();
title.moveTo([0, 3.3, 0]);

const curveLabel = new MathTex({ latex: 'y=x^2' });
await curveLabel.waitForRender();
curveLabel.moveTo(axes.c2p(1.72, 3.75));

let count = 4;
let bars = axes.getRiemannRectangles(curve, {
  xRange: [0, 2],
  dx: 2 / count,
  inputSampleType: 'right',
  color: BLUE,
  fillOpacity: 0.45,
  strokeWidth: 1.5
});

scene.add(axes, curve, bars, title, curveLabel);

const controls = new Controls(scene, { position: 'top-right', theme: 'dark', width: 270 });
controls.addSlider({
  label: 'Number of rectangles',
  min: 1,
  max: 40,
  value: count,
  step: 1,
  onChange: (val) => {
    count = Math.round(val);
    scene.remove(bars);
    bars = axes.getRiemannRectangles(curve, {
      xRange: [0, 2],
      dx: 2 / count,
      inputSampleType: 'right',
      color: BLUE,
      fillOpacity: 0.45,
      strokeWidth: 1.5
    });
    scene.add(bars);
  }
});

controls.addButton({
  label: 'Reset to 4 rectangles',
  onClick: () => {
    count = 4;
